package com.bookstore.controller; import com.bookstore.entity.Customer; import com.bookstore.service.CustomerService; import com.bookstore.service.OrderService; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; @Controller @RequestMapping("/customers") public class CustomerController{private final CustomerService service;private final OrderService orderService;public CustomerController(CustomerService s,OrderService o){service=s;orderService=o;}@GetMapping String list(Model m){m.addAttribute("items",service.findAll());return "customers/list";}@GetMapping("/new")String create(Model m){m.addAttribute("item",new Customer());return "customers/form";}@GetMapping("/edit/{id}")String edit(@PathVariable Long id,Model m){m.addAttribute("item",service.findById(id));return "customers/form";}@PostMapping("/save")String save(@Valid @ModelAttribute("item") Customer item,BindingResult r){if(r.hasErrors())return "customers/form";service.save(item);return "redirect:/customers";}@GetMapping("/delete/{id}")String delete(@PathVariable Long id){service.delete(id);return "redirect:/customers";}@GetMapping("/{id}/orders")String orders(@PathVariable Long id,Model m){m.addAttribute("customer",service.findById(id));m.addAttribute("orders",orderService.findByCustomer(id));return "customers/orders";}}